//! Rand / XorShift1024Mult / PCG32 / hash-mixer tests.
//!
//! 1. Replays upstream's own self-tests in cpp/core/rand.cpp (XorShift1024Mult::test, PCG32::test,
//!    simpleTest, Rand::runTests) against the blocks extracted to
//!    fixtures/upstream-v1.16.5/unit/rand/.
//! 2. Bit-exactness against the real C++ (fixtures/upstream-v1.16.5/unit/oracle/rand.txt,
//!    generated by oracle.cpp next to it).

// Test code keeps the shapes of upstream's tests and oracle programs (PORTING.md §11b).
#![allow(clippy::excessive_precision, clippy::manual_range_contains, clippy::mixed_case_hex_literals, clippy::needless_range_loop)]

#[macro_use]
mod common;

use common::Cases;
use common::dbits;
use common::endl;
use common::fixture;
use katago_core::core::global::Global;
use katago_core::core::hash::Hash;
use katago_core::core::rand::Rand;
use katago_core::core::rand_helpers::PCG32;
use katago_core::core::rand_helpers::XorShift1024Mult;
use katago_core::core::test::TestCommon;
use katago_core::port::digest;
use katago_core::port::math;
use katago_core::port::fmt::cpp_ostream_f64;
use katago_core::strprintf;
use katago_core::testAssert;

const F: &str = "rand";

fn expect(name: &str, out: &mut String, expected_file: &str) {
  let expected = fixture(F, expected_file);
  TestCommon::expect_string(name, out, &expected);
}

/// `out << double`
fn d(x: f64) -> String {
  cpp_ostream_f64(x)
}

wasm_test! {
fn xorshift_and_pcg32_self_tests() {
  let mut cases = Cases::new("rand::xorshift_and_pcg32_self_tests");
  XorShift1024Mult::test();
  cases.ran();
  PCG32::test();
  cases.ran();
}
}

wasm_test! {
/// upstream: simpleTest (rand.cpp) static
fn simple_test() {
  let mut cases = Cases::new("rand::simple_test");
  let mut rand = Rand::new_seed("abc");

  let expected: [u32; 24] = [
    0x1C6B83BD, 0xFB7677DB, 0x698688D5, 0xA3CD21C3, 0xD0AD5B77, 0x8F889E6E, 0x22852278, 0xD71A114D, 0x295EF301, 0xAA0CCA48, 0x0B7271BB,
    0x4FE798FB, 0x26B4DD4B, 0x78B77C1B, 0x231C4DFB, 0x17FB87C6, 0x9CC23870, 0x1C2C2CF7, 0x62D51240, 0xF1D1A7FF, 0x44C45C0A, 0xF93ACFCE,
    0x42B1D236, 0xC1069B75,
  ];

  for i in 0..24 {
    let r = rand.next_uint();
    if r != expected[i] {
      Global::fatal_error(&format!(
        "{}\n{}\n{}\nRand generated unexpected values",
        i,
        Global::uint32_to_hex_string(r),
        Global::uint32_to_hex_string(expected[i])
      ));
    }
  }
  cases.ran();

  {
    let s = "The quick brown fox jumps over the lazy dog.";
    let hash = digest::md5_get(s.as_bytes());
    testAssert!(hash[0] == 0xC209D9E4);
    testAssert!(hash[1] == 0x1CFBD090);
    testAssert!(hash[2] == 0xADFF68A0);
    testAssert!(hash[3] == 0xD0CB22DF);
  }
  cases.ran();

  let hash = digest::sha2_get256_hex("The quick brown fox jumps over the lazy dog.");
  // Upstream only prints on mismatch; the port makes it an assertion.
  assert_eq!(hash, "ef537f25c895bfa782526529a9b63d97aa631564d5d789c2b765448c8635fb6c");
  cases.ran();

  let mut out = String::new();
  let mut s = String::new();
  for i in 0..10 {
    let hash = digest::sha2_get256_hex(&s);
    out += &s;
    endl(&mut out);
    out += &hash;
    endl(&mut out);
    for _j in 0..37 {
      s.push((b'a' + (i % 26) as u8) as char);
    }
  }
  s = String::new();
  for i in 0..10 {
    let hash = digest::sha2_get512_hex(&s);
    out += &s;
    endl(&mut out);
    out += &hash;
    endl(&mut out);
    for _j in 0..37 {
      s.push((b'a' + (i % 26) as u8) as char);
    }
  }
  expect("hash test", &mut out, "simpletest.expected0.txt");
  cases.ran();
}
}

wasm_test! {
/// upstream: Rand::runTests (rand.cpp), first half
fn bit_mixer_and_global_roundtrip_tests() {
  let mut cases = Cases::new("rand::bit_mixer_and_global_roundtrip_tests");
  let mut out = String::new();
  {
    let name = "Bit mixer tests";
    out += &format!("{}\n", Hash::murmur_mix(12345));
    out += &format!("{}\n", Hash::murmur_mix(298174913));
    out += &format!("{}\n", Hash::split_mix64(1234567));
    out += &format!("{}\n", Hash::split_mix64(1234567u64.wrapping_add(0x9e3779b97f4a7c15u64)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::rrmxmx(0)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::rrmxmx(1)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::rrmxmx(0x0123456789abcdef)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::rrmxmx(0xfefefefefefefefe)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::nasam(0)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::nasam(1)));
    out += &format!("{}\n", Global::uint64_to_hex_string(Hash::nasam(0xfefefefefefefefe)));
    expect(name, &mut out, "bit-mixer-tests.expected0.txt");
    cases.ran();
  }

  for i in -10000i32..10000 {
    {
      testAssert!(i == Global::string_to_int(&Global::int_to_string(i)).unwrap());
    }
    {
      let x: i64 = i as i64;
      testAssert!(x == Global::string_to_int64(&Global::int64_to_string(x)).unwrap());
    }
    {
      let x: u64 = i as u64;
      testAssert!(x == Global::string_to_uint64(&Global::uint64_to_string(x)).unwrap());
    }
    {
      let x: u64 = i as u64;
      testAssert!(x == Global::hex_string_to_uint64(&Global::uint64_to_hex_string(x)).unwrap());
    }
    {
      let x: f32 = i as f32 / 100.0f32;
      testAssert!(x == Global::string_to_float(&Global::float_to_string(x)).unwrap());
    }
    {
      let x: f64 = i as f64 / 100.0;
      testAssert!(x == Global::string_to_double(&Global::double_to_string(x)).unwrap());
    }
    {
      let x: f64 = i as f64 / 1739.3;
      testAssert!(x == Global::string_to_double(&Global::double_to_string_high_precision(x)).unwrap());
    }
  }
  cases.ran();
}
}

wasm_test! {
/// upstream: Rand::runTests (rand.cpp), "Rand tests"
fn rand_tests() {
  let mut cases = Cases::new("rand::rand_tests");
  let mut out = String::new();
  let name = "Rand tests";
  let mut rand = Rand::new_seed("abc");

  out += "rand.nextUInt()\n";
  for _ in 0..16 {
    out += &format!("{}\n", rand.next_uint());
  }
  out += "rand.nextUInt(27)\n";
  for _ in 0..16 {
    out += &format!("{}\n", rand.next_uint_n(27));
  }
  out += "rand.nextInt()\n";
  for _ in 0..16 {
    out += &format!("{}\n", rand.next_int());
  }
  out += "rand.nextInt(-8,8)\n";
  for _ in 0..16 {
    out += &format!("{}\n", rand.next_int_a_b(-8, 8));
  }
  out += "rand.nextUInt64()\n";
  for _ in 0..16 {
    out += &format!("{}\n", rand.next_uint64());
  }
  out += "rand.nextUInt64(0xFFffffFFFFULL)\n";
  for _ in 0..16 {
    out += &format!("{}\n", Global::uint64_to_hex_string(rand.next_uint64_n(0xFFffffFFFF)));
  }
  out += "rand.nextDouble()\n";
  for _ in 0..16 {
    out += &format!("{}\n", d(rand.next_double()));
  }
  out += "rand.nextDouble(12)\n";
  for _ in 0..16 {
    out += &format!("{}\n", d(rand.next_double_n(12.0)));
  }
  out += "rand.nextDouble(-100,100)\n";
  for _ in 0..16 {
    out += &format!("{}\n", d(rand.next_double_a_b(-100.0, 100.0)));
  }
  out += "rand.nextGaussian()\n";
  for _ in 0..16 {
    out += &format!("{}\n", d(rand.next_gaussian()));
  }
  out += "rand.nextLogistic()\n";
  for _ in 0..16 {
    out += &format!("{}\n", d(rand.next_logistic()));
  }
  expect(name, &mut out, "rand-tests.expected0.txt");
  cases.ran();

  {
    let name = "nextIndexCumulative tests";
    let mut rand = Rand::new_seed(name);

    let probs: [f64; 5] = [1.0, 4.0, 2.5, 0.5, 2.0];
    let mut cum_probs: [f64; 5] = [0.0; 5];
    for i in 0..5 {
      cum_probs[i] = if i == 0 { probs[i] } else { probs[i] + cum_probs[i - 1] };
    }

    let mut frequencies: [i32; 5] = [0, 0, 0, 0, 0];
    for _i in 0..10000 {
      let r = rand.next_index_cumulative(&cum_probs, 5) as i32;
      testAssert!(r >= 0 && r < 5);
      frequencies[r as usize] += 1;
    }
    for i in 0..5 {
      out += &format!("{}\n", frequencies[i]);
    }
    expect(name, &mut out, "nextindexcumulative-tests.expected0.txt");
    cases.ran();
  }
}
}

wasm_test! {
/// upstream: Rand::runTests (rand.cpp), "Gamma tests"
fn gamma_tests() {
  let mut cases = Cases::new("rand::gamma_tests");
  let mut out = String::new();
  let name = "Gamma tests";
  let mut rand = Rand::new_seed("def");

  let tiny_subnormal: f64 = 4.9406564584124654e-324;
  let tiny_normal: f64 = 2.2250738585072014e-308;
  let max_double: f64 = 1.7976931348623157e308;
  out += &format!("pow(0.5,1e300) {}\n", d(math::powf(0.5, 1.0e300)));
  out += &format!("tinySubnormal {}\n", strprintf!("%.10g", tiny_subnormal));
  out += &format!("tinyNormal {}\n", strprintf!("%.10g", tiny_normal));
  out += &format!("maxDouble {}\n", strprintf!("%.10g", max_double));
  out += &format!("log(tinySubnormal) {}\n", strprintf!("%.10g", math::ln(tiny_subnormal)));
  out += &format!("log(tinyNormal) {}\n", strprintf!("%.10g", math::ln(tiny_normal)));

  let mut run = |out: &mut String, label: &str, a: f64, n: i32| {
    *out += label;
    endl(out);
    for _ in 0..n {
      *out += &format!("{}\n", d(rand.next_gamma(a).unwrap()));
    }
  };
  run(&mut out, "rand.nextGamma(tinySubnormal)", tiny_subnormal, 16);
  run(&mut out, "rand.nextGamma(tinyNormal)", tiny_normal, 16);
  run(&mut out, "rand.nextGamma(0.001)", 0.001, 16);
  run(&mut out, "rand.nextGamma(0.1)", 0.1, 16);
  run(&mut out, "rand.nextGamma(1)", 1.0, 16);
  run(&mut out, "rand.nextGamma(1.0000000000001)", 1.0000000000001, 16);
  run(&mut out, "rand.nextGamma(4)", 4.0, 16);
  run(&mut out, "rand.nextGamma(100)", 100.0, 16);
  run(&mut out, "rand.nextGamma(1e308)", 1e308, 8);
  run(&mut out, "rand.nextGamma(maxDouble)", max_double, 8);
  expect(name, &mut out, "gamma-tests.expected0.txt");
  cases.ran();

  {
    let inf = f64::INFINITY;
    out += &format!("pow(0.5,inf) {}\n", d(math::powf(0.5, inf)));
    out += &format!("pow(1.0,inf) {}\n", d(math::powf(1.0, inf)));
    out += &format!("log(0) {}\n", Global::double_to_string(math::ln(0.0)));
    run(&mut out, "rand.nextGamma(inf)", inf, 8);
    expect(name, &mut out, "gamma-tests.expected1.txt");
    cases.ran();
  }
}
}

wasm_test! {
/// upstream: Rand::runTests (rand.cpp), "Rand moment tests"
fn rand_moment_tests() {
  let mut cases = Cases::new("rand::rand_moment_tests");
  let mut out = String::new();
  let name = "Rand moment tests";
  let buf_len: i32 = 200000;
  let mut buf: Vec<f64> = vec![0.0; buf_len as usize];
  let print_moments = |out: &mut String,
                       buf: &Vec<f64>,
                       distr_name: &str,
                       expected_mean: f64,
                       expected_variance: f64,
                       expected_skew: f64,
                       expected_excess_kurt: f64| {
    let mut m1: f64 = 0.0;
    let mut m2: f64 = 0.0;
    let mut m3: f64 = 0.0;
    let mut m4: f64 = 0.0;
    for i in 0..buf_len {
      let x = buf[i as usize];
      m1 += x;
      m2 += x * x;
      m3 += x * x * x;
      m4 += x * x * x * x;
    }
    m1 /= buf_len as f64;
    m2 /= buf_len as f64;
    m3 /= buf_len as f64;
    m4 /= buf_len as f64;
    let mean = m1;
    let variance = m2 - m1 * m1;
    let skew = (m3 - 3.0 * m1 * variance - m1 * m1 * m1) / (variance * variance * variance).sqrt();
    let excess_kurt = (m4 - 4.0 * m3 * m1 + 6.0 * m2 * m1 * m1 - 3.0 * m1 * m1 * m1 * m1) / (variance * variance) - 3.0;
    *out += &strprintf!("%s sample: Mean %f Variance %f Skew %f ExcessKurt %f", distr_name, mean, variance, skew, excess_kurt);
    endl(out);
    *out += &strprintf!(
      "%s expected: Mean %f Variance %f Skew %f ExcessKurt %f",
      distr_name,
      expected_mean,
      expected_variance,
      expected_skew,
      expected_excess_kurt
    );
    endl(out);
  };
  let mut rand = Rand::new_seed("test");
  for i in 0..buf_len as usize {
    buf[i] = rand.next_double();
  }
  print_moments(&mut out, &buf, "Uniform", 0.5, 1.0 / 12.0, 0.0, -6.0 / 5.0);
  for i in 0..buf_len as usize {
    buf[i] = rand.next_gaussian();
  }
  print_moments(&mut out, &buf, "Gaussian", 0.0, 1.0, 0.0, 0.0);
  #[allow(clippy::approx_constant)] // upstream's literal, verbatim
  let pi: f64 = 3.14159265358979323846264;
  for i in 0..buf_len as usize {
    buf[i] = rand.next_logistic();
  }
  print_moments(&mut out, &buf, "Logistic", 0.0, pi * pi / 3.0, 0.0, 1.2);
  for i in 0..buf_len as usize {
    buf[i] = rand.next_exponential();
  }
  print_moments(&mut out, &buf, "Exponential", 1.0, 1.0, 2.0, 6.0);
  for i in 0..buf_len as usize {
    buf[i] = rand.next_gamma(0.05).unwrap();
  }
  print_moments(&mut out, &buf, "Gamma(0.05)", 0.05, 0.05, 2.0 / 0.05f64.sqrt(), 6.0 / 0.05);
  for i in 0..buf_len as usize {
    buf[i] = rand.next_gamma(0.5).unwrap();
  }
  print_moments(&mut out, &buf, "Gamma(0,5)", 0.5, 0.5, 2.0 / 0.5f64.sqrt(), 6.0 / 0.5);
  for i in 0..buf_len as usize {
    buf[i] = rand.next_gamma(1.01).unwrap();
  }
  print_moments(&mut out, &buf, "Gamma(1.01)", 1.01, 1.01, 2.0 / 1.01f64.sqrt(), 6.0 / 1.01);
  for i in 0..buf_len as usize {
    buf[i] = rand.next_gamma(4.0).unwrap();
  }
  print_moments(&mut out, &buf, "Gamma(4.0)", 4.0, 4.0, 2.0 / 4.0f64.sqrt(), 6.0 / 4.0);
  expect(name, &mut out, "rand-moment-tests.expected0.txt");
  cases.ran();
}
}

