wasm_test! {
/// Mirrors `randMode()` in fixtures/upstream-v1.16.5/unit/oracle/oracle.cpp.
fn rand_bit_exact_vs_cpp() {
  let mut cases = Cases::new("rand::rand_bit_exact_vs_cpp");
  let expected = fixture("oracle", "rand.txt");
  let mut out = String::new();
  let str_seeds: Vec<String> = vec![
    "abc".to_string(),
    "".to_string(),
    "Board::initHash()".to_string(),
    "seed with spaces and \u{fc}nicode".to_string(),
    "x".repeat(100),
    "runBoardUndoTests".to_string(),
  ];
  let u64_seeds: Vec<u64> = vec![0, 1, 0xDEADBEEFCAFEBABE];
  let total = str_seeds.len() + u64_seeds.len();
  for si in 0..total {
    let mut rand = if si < str_seeds.len() {
      out += &format!("seedstr {}\n", str_seeds[si]);
      Rand::new_seed(&str_seeds[si])
    } else {
      out += &format!("seedu64 {}\n", Global::uint64_to_hex_string(u64_seeds[si - str_seeds.len()]));
      Rand::new_seed_u64(u64_seeds[si - str_seeds.len()])
    };
    out += &format!("getSeed {}\n", rand.get_seed());
    for _ in 0..8 {
      out += &format!("nextUInt {}\n", rand.next_uint());
    }
    for _ in 0..8 {
      out += &format!("nextUInt(27) {}\n", rand.next_uint_n(27));
    }
    for _ in 0..2 {
      out += &format!("nextUInt(1) {}\n", rand.next_uint_n(1));
    }
    for _ in 0..4 {
      out += &format!("nextUInt(0xFFFFFFFF) {}\n", rand.next_uint_n(0xFFFFFFFF));
    }
    for _ in 0..4 {
      out += &format!("nextInt {}\n", rand.next_int());
    }
    for _ in 0..4 {
      out += &format!("nextInt(-8,8) {}\n", rand.next_int_a_b(-8, 8));
    }
    for _ in 0..2 {
      out += &format!("nextInt(INT_MIN,INT_MAX) {}\n", rand.next_int_a_b(i32::MIN, i32::MAX));
    }
    for _ in 0..4 {
      out += &format!("nextUInt64 {}\n", Global::uint64_to_hex_string(rand.next_uint64()));
    }
    for _ in 0..4 {
      out += &format!("nextUInt64(1000000007) {}\n", rand.next_uint64_n(1000000007));
    }
    for _ in 0..2 {
      out += &format!("nextUInt64(2^63+5) {}\n", rand.next_uint64_n((1u64 << 63) + 5));
    }
    for _ in 0..4 {
      out += &format!("nextDouble {}\n", dbits(rand.next_double()));
    }
    for _ in 0..2 {
      out += &format!("nextDouble(12) {}\n", dbits(rand.next_double_n(12.0)));
    }
    for _ in 0..2 {
      out += &format!("nextDouble(-100,100) {}\n", dbits(rand.next_double_a_b(-100.0, 100.0)));
    }
    for _ in 0..4 {
      out += &format!("nextBool(0.3) {}\n", rand.next_bool(0.3) as i32);
    }
    for _ in 0..5 {
      out += &format!("nextGaussian {}\n", dbits(rand.next_gaussian()));
    }
    for _ in 0..3 {
      out += &format!("nextGaussianTruncated(1.5) {}\n", dbits(rand.next_gaussian_truncated(1.5)));
    }
    for _ in 0..3 {
      out += &format!("nextExponential {}\n", dbits(rand.next_exponential()));
    }
    for _ in 0..3 {
      out += &format!("nextLogistic {}\n", dbits(rand.next_logistic()));
    }
    for _ in 0..3 {
      out += &format!("nextGamma(0.5) {}\n", dbits(rand.next_gamma(0.5).unwrap()));
    }
    for _ in 0..3 {
      out += &format!("nextGamma(1) {}\n", dbits(rand.next_gamma(1.0).unwrap()));
    }
    for _ in 0..3 {
      out += &format!("nextGamma(4.5) {}\n", dbits(rand.next_gamma(4.5).unwrap()));
    }
    {
      let freq: [i32; 5] = [1, 0, 3, 7, 2];
      for _ in 0..4 {
        out += &format!("nextUInt(freq) {}\n", rand.next_uint_freq_n(&freq, 5));
      }
      let rel_probs: [f64; 4] = [0.5, 1.5, 0.0, 2.0];
      for _ in 0..4 {
        out += &format!("nextUInt(relProbs) {}\n", rand.next_uint_rel_probs_n(&rel_probs, 4));
      }
      let cum: [f64; 4] = [1.0, 3.0, 3.5, 7.0];
      for _ in 0..4 {
        out += &format!("nextIndexCumulative {}\n", rand.next_index_cumulative(&cum, 4));
      }
    }
    {
      let mut buf: [u32; 12] = [0; 12];
      rand.fill_shuffled_uint_range(12, &mut buf).unwrap();
      out += "fillShuffledUIntRange(12)";
      for x in buf {
        out += &format!(" {}", x);
      }
      endl(&mut out);
      let mut v: Vec<i32> = (0..10).collect();
      rand.shuffle(&mut v);
      out += "shuffle";
      for x in v {
        out += &format!(" {}", x);
      }
      endl(&mut out);
    }
    out += &format!("nextUInt {}\n", rand.next_uint());
    cases.ran();
  }
  common::compare_lines("oracle/rand.txt", &out, &expected);
}
}
